select.where:
 del_flag = 0
and CX_ORDER_NO = #{cxOrderNo}
 and  schedule_date = #{scheduleDate}
 and  schedule_date = to_date(#{scheduleDateStr},'yyyyMMdd')
 and  data_source = #{dataSource}

mapper.select:
select clm.cx_order_no, regexp_replace( LISTAGG(lmi.machine_name, ',') WITHIN GROUP (ORDER BY lmi.machine_name), '([^,]+)(,\1)+','\1' ) lh_MachineNames from t_cx_change_lh_machine clm left join t_lh_machine_info lmi on clm.lh_machine_code=lmi.machine_code
clm.del_flag='0' and lmi.del_flag='0' and clm.CX_ORDER_NO = #{cxOrderNo} and clm.schedule_date = to_date(#{scheduleDateStr},'yyyyMMdd') and clm.data_source = #{dataSource}
group by clm.cx_order_no

mapper.delete:
update t_cx_change_lh_machine set del_flag='1'

    del_flag='0'
    and CX_ORDER_NO = #{cxOrderNo}
     and  schedule_date = to_date(#{scheduleDateStr},'yyyyMMdd')
     and  data_source = #{dataSource}

mapper.insert:
insert into t_cx_change_lh_machine (id,cx_order_no, schedule_date, lh_machine_code, change_type,embryo_stock, change_mold_time, use_mold_num, data_source, create_by, update_by, update_time, remark) select seq_cx_change_lh_machine.NEXTVAL AS ID, x.* from (
select #{cxChangeLhMachine.cxOrderNo,jdbcType=VARCHAR}, #{cxChangeLhMachine.scheduleDate}, #{cxChangeLhMachine.lhMachineCode,jdbcType=VARCHAR}, #{cxChangeLhMachine.changeType,jdbcType=VARCHAR}, #{cxChangeLhMachine.embryoStock,jdbcType=INTEGER}, #{cxChangeLhMachine.changeMoldTime,jdbcType=DATE}, #{cxChangeLhMachine.useMoldNum,jdbcType=INTEGER}, #{cxChangeLhMachine.dataSource,jdbcType=VARCHAR}, #{cxChangeLhMachine.createBy,jdbcType=VARCHAR}, #{cxChangeLhMachine.updateBy,jdbcType=VARCHAR}, #{cxChangeLhMachine.updateTime,jdbcType=DATE}, #{cxChangeLhMachine.remark,jdbcType=VARCHAR} from dual
) x
